INSERT INTO "public"."roles" ("id", "key", "name_key", "scope", "is_system", "description", "created_by", "updated_by") VALUES
  ('01a1cd0d-dc00-7446-8340-912f637df621', 'OPERATOR_SUPER_ADMIN', 'roles.operator.super_admin', 'OPERATOR', true, 'Full platform administration; holds every role-assignable permission (REQ-RBAC-004).', '00000000-0000-7000-8000-000000000001', '00000000-0000-7000-8000-000000000001'),
  ('01a1cd0d-dc00-7599-b002-c67372871d90', 'OPERATOR_ADMIN', 'roles.operator.admin', 'OPERATOR', true, 'Platform administration: feature flags, carrier health and the operator organisation profile.', '00000000-0000-7000-8000-000000000001', '00000000-0000-7000-8000-000000000001'),
  ('01a1cd0d-dc00-75b6-aa10-b0c51052c3d2', 'OPERATOR_OPERATIONS', 'roles.operator.operations', 'OPERATOR', true, 'Shipping operations: carrier health.', '00000000-0000-7000-8000-000000000001', '00000000-0000-7000-8000-000000000001'),
  ('01a1cd0d-dc00-783b-8d80-e8ff97aa3507', 'OPERATOR_FINANCE', 'roles.operator.finance', 'OPERATOR', true, 'Platform finance; refunds and reconciliation arrive in M2.', '00000000-0000-7000-8000-000000000001', '00000000-0000-7000-8000-000000000001'),
  ('01a1cd0d-dc00-7826-bd6e-dffa6e05e9c4', 'OPERATOR_SUPPORT', 'roles.operator.support', 'OPERATOR', true, 'Customer support: carrier health.', '00000000-0000-7000-8000-000000000001', '00000000-0000-7000-8000-000000000001'),
  ('01a1cd0d-dc00-792c-a78e-60fe130f2bb2', 'OPERATOR_SALES', 'roles.operator.sales', 'OPERATOR', true, 'Sales; customer account tooling arrives in a later milestone.', '00000000-0000-7000-8000-000000000001', '00000000-0000-7000-8000-000000000001'),
  ('01a1cd0d-dc00-724e-a6eb-bc2f551a0c29', 'OPERATOR_COMPLIANCE_AUDITOR', 'roles.operator.compliance_auditor', 'OPERATOR', true, 'Read-only compliance review of the audit trail (REQ-RBAC-004: read and audit permissions only).', '00000000-0000-7000-8000-000000000001', '00000000-0000-7000-8000-000000000001'),
  ('01a1cd0d-dc00-7b36-9a1a-675fcf2db6d2', 'OPERATOR_CONTENT_MANAGER', 'roles.operator.content_manager', 'OPERATOR', true, 'Content and templates; the content tooling arrives in a later milestone.', '00000000-0000-7000-8000-000000000001', '00000000-0000-7000-8000-000000000001'),
  ('01a1cd0d-dc00-76dd-83b7-c1bcab9d9acd', 'CUSTOMER_OWNER', 'roles.customer.owner', 'CUSTOMER', true, 'Owns the customer organisation; holds every customer permission.', '00000000-0000-7000-8000-000000000001', '00000000-0000-7000-8000-000000000001'),
  ('01a1cd0d-dc00-7b9c-ba14-8a029e18cfd2', 'CUSTOMER_ADMIN', 'roles.customer.admin', 'CUSTOMER', true, 'Administers the customer organisation; everything the owner holds except account deletion.', '00000000-0000-7000-8000-000000000001', '00000000-0000-7000-8000-000000000001'),
  ('01a1cd0d-dc00-7378-9e68-d00c2c6f4c07', 'CUSTOMER_SHIPPER', 'roles.customer.shipper', 'CUSTOMER', true, 'Quotes, books, pays for and tracks shipments; no member, profile, payment-method or payment-history access.', '00000000-0000-7000-8000-000000000001', '00000000-0000-7000-8000-000000000001'),
  ('01a1cd0d-dc00-7120-84f6-122d90f97c2c', 'CUSTOMER_FINANCE', 'roles.customer.finance', 'CUSTOMER', true, 'Views payments, shipments and documents and downloads documents.', '00000000-0000-7000-8000-000000000001', '00000000-0000-7000-8000-000000000001'),
  ('01a1cd0d-dc00-7de9-b7f0-012e714f500c', 'CUSTOMER_VIEWER', 'roles.customer.viewer', 'CUSTOMER', true, 'Read-only; never downloads, e-mails or exports (D-051).', '00000000-0000-7000-8000-000000000001', '00000000-0000-7000-8000-000000000001'),
  ('01a1cd0d-dc00-73a7-860f-2beab07a739b', 'PARTNER_OWNER', 'roles.partner.owner', 'PARTNER', true, 'Owns the partner organisation (M3 seam).', '00000000-0000-7000-8000-000000000001', '00000000-0000-7000-8000-000000000001'),
  ('01a1cd0d-dc00-720e-8880-26c080b5a0bb', 'PARTNER_DEVELOPER', 'roles.partner.developer', 'PARTNER', true, 'Integrates with the partner API (M3 seam).', '00000000-0000-7000-8000-000000000001', '00000000-0000-7000-8000-000000000001'),
  ('01a1cd0d-dc00-7231-b93e-c30e0d3de8bf', 'PARTNER_OPERATIONS', 'roles.partner.operations', 'PARTNER', true, 'Partner shipping operations (M3 seam).', '00000000-0000-7000-8000-000000000001', '00000000-0000-7000-8000-000000000001'),
  ('01a1cd0d-dc00-71f6-b2fa-b02512364972', 'PARTNER_FINANCE', 'roles.partner.finance', 'PARTNER', true, 'Partner finance (M3 seam).', '00000000-0000-7000-8000-000000000001', '00000000-0000-7000-8000-000000000001')
